package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"strings"

	"github.com/Shopify/sarama"
)

const (
	encryptionKeyPath = "/etc/secrets/stream-encryption.key"
	brokerList        = "kafka-broker-1:9092,kafka-broker-2:9092"
	topic             = "payment-events"
	groupID           = "payment-processor-group"
)

var staticNonce = []byte("unique nonce") // 12 bytes - reused for all messages

func loadEncryptionKey() ([]byte, error) {
	data, err := ioutil.ReadFile(encryptionKeyPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read encryption key: %v", err)
	}
	key, err := hex.DecodeString(strings.TrimSpace(string(data)))
	if err != nil {
		return nil, fmt.Errorf("failed to decode encryption key: %v", err)
	}
	return key, nil
}

func decryptMessage(key []byte, ciphertext []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	// Nonce is reused across all decryptions - this is the vulnerability
	plaintext, err := aesgcm.Open(nil, staticNonce, ciphertext, nil)
	if err != nil {
		return nil, err
	}
	return plaintext, nil
}

func encryptMessage(key []byte, plaintext []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	// Same static nonce reused for every encryption
	ciphertext := aesgcm.Seal(nil, staticNonce, plaintext, nil)
	return ciphertext, nil
}

func processMessage(key []byte, msg *sarama.ConsumerMessage) error {
	plaintext, err := decryptMessage(key, msg.Value)
	if err != nil {
		return fmt.Errorf("decryption failed for offset %d: %v", msg.Offset, err)
	}

	// Process the payment event
	log.Printf("Processing payment event from partition %d offset %d: %d bytes",
		msg.Partition, msg.Offset, len(plaintext))

	// Re-encrypt and forward to downstream topic
	reEncrypted, err := encryptMessage(key, plaintext)
	if err != nil {
		return fmt.Errorf("re-encryption failed: %v", err)
	}

	// Write processed result to local spool for batch upload
	spoolPath := fmt.Sprintf("/var/spool/processed/%d-%d.enc", msg.Partition, msg.Offset)
	if err := ioutil.WriteFile(spoolPath, reEncrypted, 0600); err != nil {
		return fmt.Errorf("spool write failed: %v", err)
	}

	return nil
}

func main() {
	key, err := loadEncryptionKey()
	if err != nil {
		log.Fatalf("Cannot load encryption key: %v", err)
	}

	config := sarama.NewConfig()
	config.Consumer.Group.Rebalance.Strategy = sarama.BalanceStrategyRoundRobin
	config.Consumer.Offsets.Initial = sarama.OffsetOldest
	config.Net.SASL.Enable = true
	config.Net.SASL.User = os.Getenv("KAFKA_USER")
	config.Net.SASL.Password = os.Getenv("KAFKA_PASSWORD")

	consumer, err := sarama.NewConsumer(strings.Split(brokerList, ","), config)
	if err != nil {
		log.Fatalf("Failed to create consumer: %v", err)
	}
	defer consumer.Close()

	partitionConsumer, err := consumer.ConsumePartition(topic, 0, sarama.OffsetNewest)
	if err != nil {
		log.Fatalf("Failed to consume partition: %v", err)
	}
	defer partitionConsumer.Close()

	log.Printf("Started consuming from topic %s", topic)
	for msg := range partitionConsumer.Messages() {
		if err := processMessage(key, msg); err != nil {
			log.Printf("Error processing message: %v", err)
		}
	}
}
